    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0) && B.size(1) == 1, "Shape mismatch");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    int M = A_c.size(0);
    int K = A_c.size(1);
    auto C = torch::zeros({M, 1}, A_c.options());
